import{_ as a,o as i,c as o,a0 as d}from"./chunks/framework.DbCRPtfr.js";const u=JSON.parse('{"title":"构建与打包","description":"","frontmatter":{},"headers":[],"relativePath":"guide/build.md","filePath":"guide/build.md","lastUpdated":1791391065000}'),s={name:"guide/build.md"};function t(l,e,n,c,p,r){return i(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="构建与打包" tabindex="-1">构建与打包 <a class="header-anchor" href="#构建与打包" aria-label="Permalink to &quot;构建与打包&quot;">​</a></h1><h2 id="构建流水线" tabindex="-1">构建流水线 <a class="header-anchor" href="#构建流水线" aria-label="Permalink to &quot;构建流水线&quot;">​</a></h2><p>所有构建经 <code>vp run</code>（vite-plus 任务流水线）编排，以 <code>apps/desktop</code> 的 <code>build</code> 脚本为入口：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 构建 + 打出完整安装包（当前平台）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:dir</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 构建 + 仅产出免安装目录（验证打包首选，速度快）</span></span></code></pre></div><p>内部拆解为三个任务，由 vp 负责顺序与缓存：</p><ol><li><code>clean</code> —— 清理旧产物（<code>apps/desktop/dist</code>、<code>apps/desktop/build</code> 中非图标内容）；</li><li><code>build:electron</code> —— rolldown 并行编译 main 与 preload（单文件 CJS bundle，输出到 <code>apps/desktop/dist/electron/main/</code>）；</li><li><code>build:renderer</code> —— vite-plus 构建渲染层。</li></ol><p><strong>缓存</strong>：源码未变化的任务在下次构建时直接命中缓存跳过（缓存按文件哈希失效，改哪个文件只重跑受影响的任务；删除 <code>dist</code> 后命中缓存也能完整还原产物）。脚手架默认已开启 <code>--cache</code>。</p><h2 id="electron-builder-配置" tabindex="-1">electron-builder 配置 <a class="header-anchor" href="#electron-builder-配置" aria-label="Permalink to &quot;electron-builder 配置&quot;">​</a></h2><p>打包配置在 <code>apps/desktop/build.json</code>（不再内联于 package.json）：</p><ul><li><code>files: [&quot;dist/electron/**/*&quot;]</code>——只打包构建产物，不携带 node_modules；</li><li><code>directories.output: &quot;build&quot;</code>——安装包输出到 <code>apps/desktop/build/</code>；</li><li><code>afterPack</code> 钩子（<code>afterPack.mjs</code>）负责把 <code>rootLib/&lt;平台&gt;/&lt;架构&gt;</code> 的二进制资源拷入应用。注意 <strong>electron-builder 26.17 校验钩子必须位于应用目录内</strong>，因此该文件不能移动到 <code>tools/build</code>；</li><li>Windows 图标在 <code>apps/desktop/build/icons/</code>。</li></ul><p>各平台产物：Windows 生成 nsis 安装器，macOS 生成 dmg（本机装有签名证书时会自动签名），Linux 生成 AppImage/deb。</p><h2 id="web-版本" tabindex="-1">Web 版本 <a class="header-anchor" href="#web-版本" aria-label="Permalink to &quot;Web 版本&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:web</span></span></code></pre></div><p>仅构建渲染层为纯 Web 应用（<code>apps/desktop/dist/web</code>）。注意 Web 环境下不可调用任何 electron API；可用 <code>window.ipcBridge</code> 是否存在来区分运行环境。</p><h2 id="环境文件" tabindex="-1">环境文件 <a class="header-anchor" href="#环境文件" aria-label="Permalink to &quot;环境文件&quot;">​</a></h2><p><code>apps/desktop/env/</code> 下按 <code>.环境名.env</code> 约定存放 dotenv 文件，<code>-m</code> 参数选择环境（未传时用 <code>.env</code>）。env 中定义的变量会注入构建配置（<code>getConfig</code>），渲染层通过编译期宏 <code>__CONFIG__</code> 访问。</p><h2 id="主进程产物形态" tabindex="-1">主进程产物形态 <a class="header-anchor" href="#主进程产物形态" aria-label="Permalink to &quot;主进程产物形态&quot;">​</a></h2><p>主进程始终输出为<strong>单文件 CJS bundle</strong>（<code>main.cjs</code>，electron/semver 为 external，其余依赖全部内联）。这是刻意的：单文件加载最快，也是<a href="/electron-vite-template/guide/bytecode">字节码保护</a>的先决条件。启用字节码后该文件会被替换为 loader 壳 + <code>main.bin</code>，构建链路的其余部分完全不变。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>打包出的应用启动即崩溃</strong>：检查 <code>apps/desktop/package.json</code> 的 <code>main</code> 字段是否指向 <code>./dist/electron/main/main.cjs</code>，以及 <code>dist</code> 是否由当前代码构建（改完代码记得重新构建再打包）；</li><li><strong>依赖装完但构建找不到模块</strong>：确认依赖声明在使用它的包里。pnpm 严格解析下&quot;别人装了我也能用&quot;（幽灵依赖）不再成立；</li><li><strong>签名失败（macOS）</strong>：CI 或无证书环境可在环境变量中设置 <code>CSC_IDENTITY_AUTO_DISCOVERY=false</code> 跳过签名。</li></ul>`,20)])])}const b=a(s,[["render",t]]);export{u as __pageData,b as default};
